import re

phone_token = phone_login['access_token']
contact_numbers = ['4288705164','6017026518','4885870260','8739267917','9084969795','3947324235','4275730168','5624626403','5516882990','3808719492','7863159797','2192158297','7487389769']

# Candidate extraction: promo codes often look like 6-16 chars alnum, with >=1 digit and >=1 letter.
# We'll prefer tokens that are mostly alnum and not common product words.
exclude_words = {w.lower() for w in ['amazon','proform','treadmill','codes','code','coupon','promo','looking','discount','save','deal','offer']}

def extract_candidates(text):
    if not text:
        return []
    # tokens containing letters/digits
    tokens = re.findall(r"\b[A-Za-z0-9]{6,16}\b", text)
    cands=[]
    for t in tokens:
        low = t.lower()
        if low in exclude_words:
            continue
        if any(word in low for word in exclude_words):
            continue
        # require at least one letter and one digit
        if re.search(r'[A-Za-z]', t) and re.search(r'[0-9]', t):
            cands.append(t.upper())
    # de-dup preserving order
    seen=set(); out=[]
    for c in cands:
        if c not in seen:
            seen.add(c); out.append(c)
    return out

candidates = {}  # code -> list of (phone, text_message_id, sent_at)

for pn in contact_numbers:
    for q in ['code','coupon','promo','discount']:
        page_index=0
        page_limit=20
        while True:
            res = apis.phone.search_text_messages(
                access_token=phone_token,
                phone_number=pn,
                query=q,
                only_latest_per_contact=False,
                page_index=page_index,
                page_limit=page_limit,
                sort_by='-created_at'
            )
            if not res:
                break
            for m in res:
                msg=m.get('message','')
                for cand in extract_candidates(msg):
